package com.medtrack.transfer.dto; import com.medtrack.transfer.entity.*; import java.util.*; public record TransferResponse(UUID id,String transferNumber,String status,UUID sourceWarehouseId,UUID destinationWarehouseId,List<Item>items){public record Item(UUID batchId,UUID medicineId,int requestedQuantity,int allocatedQuantity,int pickedQuantity,int dispatchedQuantity,int receivedQuantity,int damagedQuantity){}public static TransferResponse of(StockTransfer t){return new TransferResponse(t.getId(),t.getTransferNumber(),t.getStatus().name(),t.getSourceWarehouse().getId(),t.getDestinationWarehouse().getId(),t.getItems().stream().map(i->new Item(i.getBatch()==null?null:i.getBatch().getId(),i.getMedicine().getId(),i.getRequestedQuantity(),i.getAllocatedQuantity(),i.getPickedQuantity(),i.getDispatchedQuantity(),i.getReceivedQuantity(),i.getDamagedQuantity())).toList());}}
